export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "07:45。M-00 外部醫療區。不是病房。是病房旁邊一間隔出來的觀察室。中間有一面牆。牆上有安全視訊。螢幕裡是紗英的床側。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪坐在觀察室裡。她不進去。她不能進去。紗英的同意不能由家屬在場引導。患者權利代表在螢幕另一側——病房裡面。外部醫師也在裡面。呼吸治療師在床邊。獨立系統安全人員在觀察室的另一端，看著另一個螢幕——技術記錄。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原坐在觀察室角落。她不說話。她只是看。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她在裡面。螢幕裡。紗英。我的母親。被宣稱多年前病逝的人。現在躺在 M-00 外部醫療區的床上。雙向穩定閉環。半昏迷。發聲閥在她喉部。她能說話。極少。極短。像在節省最後的能量。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "07:50。外部醫師走到紗英床邊。他坐下。他的動作很慢。像在靠近一個隨時可能碎掉的東西。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "紗英女士。我是外部醫療的醫師。我不屬於這間設施。今天要問妳幾個問題。不是關於過去。是關於——妳的資料未來可以被怎麼用。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕裡。紗英的眼睛動了一下。很慢。半睜。她沒有點頭。但她的嘴唇——動了。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯嗯。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraSae_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "很輕。像氣流通過一條很窄的縫。呼吸治療師看了一下監測儀。血氧穩定。呼吸頻率在可接受範圍。他對外部醫師點頭。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她的聲音。我透過螢幕聽見她的聲音。很薄。很小心。像踩在很薄的冰上。可是——她是清醒的。她在聽。她知道有人在那裡。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "07:55。外部醫師開始第一段。用途。逐項。普通語言。沒有技術欄位。沒有英文代碼。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "第一個問題。可以用妳過去已經存在的醫療數字，幫其他病人慢慢離開這套機器嗎？", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "紗英沒有立刻回答。她的眼睛看著天花板。很慢。像在讀一個只有她看得見的東西。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯可以。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraSae_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "患者權利代表在旁邊。她看著紗英。不是看監測儀。是看她的表情。她的眼睛。她的呼吸節奏。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.PatientRightsRep, character: "患者權利代表", dialogue: "紗英女士。妳說「可以」。妳的意思是——可以用妳已經存在的醫療數字，幫助其他病人慢慢離開中央系統。是這樣嗎？", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯是。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraSae_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "患者權利代表點頭。很輕。她在手寫板上記了一行。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她在確認。不是確認紗英說了什麼。是確認——紗英理解了什麼。她說的「可以」是不是真的意思是「可以」。不是迎合。不是疲勞。不是因為覺得應該答應。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "08:00。外部醫師繼續。第二項。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "第二個問題。可以把這些資料拿去給東京的公共提示系統使用嗎？", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "紗英的眼睛動了一下。她的手指——在床單上收了一下。很輕。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯不要。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraSae_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "兩個字。比「可以」更清楚。更用力。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她拒絕了。公共提示系統。她知道那是什麼。她知道——那是把她的資料送進公共廣播。送進 TOKYO-7。送進那個——把她困在閉環裡十年的系統。她不要。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "患者權利代表再確認。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.PatientRightsRep, character: "患者權利代表", dialogue: "妳說「不要」。妳的意思是——不可以把妳的資料拿去給公共提示系統使用。是這樣嗎？", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯是。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraSae_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "08:05。外部醫師。第三項。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "第三個問題。可以把妳完整的腦部資料送出去嗎？", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "紗英的呼吸變了一下。不是變快。是——變深。像在準備說一個更重的字。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯不要。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraSae_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "呼吸治療師看了一下血氧。穩定。他對外部醫師點頭。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.PatientRightsRep, character: "患者權利代表", dialogue: "妳拒絕完整的腦部資料送出。是嗎？", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯是。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraSae_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）原始神經流。她拒絕了。她不要自己的完整腦部資料被送出去。不是因為她不懂。是因為——她懂。她在這套系統裡躺了十年。她知道「完整腦部資料」意味著什麼。意味著——可以被複製。可以被當成模板。可以被當成新的母體。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "08:10。外部醫師。第四項。最後一項。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "第四個問題。如果只留下拆線時不能跨過的安全範圍，可以嗎？", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "紗英沒有立刻回答。她的眼睛半閉。像在計算。不是數字。是——界線。她在想——什麼是可以給的。什麼是不能跨過的。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯可以。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraSae_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "患者權利代表確認。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.PatientRightsRep, character: "患者權利代表", dialogue: "妳的意思是——只留下拆線時不能跨過的安全範圍。其他資料可以用來幫助患者分離。是這樣嗎？", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯是。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraSae_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "08:15。外部醫師退後一步。他對患者權利代表點頭。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "第一段完成。休息十分鐘。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "紗英的眼睛閉上了。呼吸治療師調整了發聲閥的負荷。很輕。監測儀上的數值穩定下來。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她答應了——幫助患者分離。她拒絕了——公共使用。完整腦部資料。她只允許——留下拆線時不能跨過的安全範圍。她不是在說「繼續維持」。她是在說——可以用我的東西幫別人離開。但不可以把我送出去。不可以把我變成新的模板。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "08:25。觀察室裡。澪看著螢幕。紗英的眼睛閉著。呼吸很慢。很穩。像一個人在很深的水面上漂浮。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原坐在角落。她一直沒有說話。她的眼睛看著螢幕。她的表情沒有變化。但——她的手放在膝蓋上。手指沒有收緊。也沒有放鬆。是——停在中間。像一個正在被重新計算的東西。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她在看。凪原在看。她看見了什麼？她看見——一個被她設計的系統困了十年的人。在用最少的力氣。說出最精確的界線。她看見——紗英不是在維持系統。她是在——規定系統怎麼被拆除。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "08:30。休息結束。外部醫師回到床邊。紗英的眼睛睜開了。很慢。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "紗英女士。休息夠了嗎？", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯嗯。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraSae_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "08:35。第二段。反向確認。外部醫師的語氣沒有變。還是那麼平。那麼慢。但問題——反過來了。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "第一個問題。如果資料可能被公共系統使用，要不要停止？", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯停止。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraSae_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "患者權利代表確認。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.PatientRightsRep, character: "患者權利代表", dialogue: "如果未來妳的資料可能被公共系統使用——妳要停止。是嗎？", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯是。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraSae_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "08:40。外部醫師。第二項。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "如果有人要求完整腦波，要不要停止？", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯停止。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraSae_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的聲音比第一段更清楚。不是更大。是——更確定。像一條線被反覆測試過。沒有斷。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）一致。第一段她拒絕公共使用。反向再問——她還是拒絕。第一段她拒絕完整腦部資料。反向再問——她還是拒絕。不是迎合。不是疲勞。是——她真的這樣想。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "08:45。外部醫師。第三項。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "如果只使用短期網路過渡限制，是否仍同意？", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "紗英停了一下。她的眼睛看著外部醫師。像在確認——「短期」是什麼意思。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯同意。⋯⋯短期。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraSae_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "兩個詞。中間有一個很長的停頓。像在用力把兩個東西放在一起。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.PatientRightsRep, character: "患者權利代表", dialogue: "妳同意短期網路過渡限制。不是永久。是短期。是嗎？", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯是。⋯⋯不是永久。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraSae_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "08:50。外部醫師。第四項。最後一項。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "以後可以改變主意嗎？", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "紗英的眼睛動了一下。她的嘴角——幾乎看不見地——動了。不是微笑。是——確認。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯可以。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraSae_Determined },
    { characterId: CharacterId.PatientRightsRep, character: "患者權利代表", dialogue: "妳知道——以後可以隨時改變主意。可以停止。可以撤回。是嗎？", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯是。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraSae_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "08:55。外部醫師退後一步。他看著患者權利代表。患者權利代表看著她的手寫板。兩段。四項。八個回答。她逐一比對。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.PatientRightsRep, character: "患者權利代表", dialogue: "兩段回答一致。第一段——允許患者分離。允許短期網路過渡限制。拒絕公共使用。拒絕完整腦部資料。第二段——反向確認。一致。沒有矛盾。沒有模糊。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她頓了一下。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.PatientRightsRep, character: "患者權利代表", dialogue: "她理解用途。回答不是單純迎合。疲勞沒有使答案失真。她知道可以拒絕。她拒絕了該拒絕的。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）一致。兩段。八個回答。沒有矛盾。她不是在應付。不是在配合。她——真的在想。用她剩下的全部力氣。在想。然後——說出界線。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:00。外部醫師回到床邊。他的聲音更慢了。像在靠近一個更脆弱的東西。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "紗英女士。還有一件事。如果有人已經正在慢慢換線——慢慢離開這套機器——而妳之後說停止，我們不會突然把線剪斷。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他頓了一下。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "會先停在最近的安全位置。再停止使用妳的資料。不會因為妳撤回——就讓正在換線的人失去保護。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "紗英的眼睛看著他。很慢。很久。她的嘴唇動了。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraSae, character: "朝倉紗英", dialogue: "⋯⋯好。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraSae_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "一個字。很輕。但——不是答應。是理解。她理解了——她的撤回不會變成另一個人的危險。她可以停止。而且——停止也是安全的。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）SAFE PAUSE。不是突然剪線。是——停在最近的安全位置。然後停止使用她的資料。她可以撤回。撤回不會害死別人。這是——她被給予的東西。不是權力。是——安心。她可以安心地說停止。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:05。呼吸治療師在紗英的溝通板上新增一個永久選項。兩個字。紅色。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "STOP／NO USE。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "溝通板掛在床邊。紗英的手指能碰到。任何時候。她只需要碰一下。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）永久。STOP。NO USE。它一直在那裡。她隨時可以碰。隨時可以停止。不是一次性的同意。是——持續的權利。每一天。每一秒。她都可以說不。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:08。外部醫師把兩段回答整理成系統記錄。他念出來。讓患者權利代表核對。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "```text PATIENT SEPARATION           YES PUBLIC USE                   NO RAW NEURAL STREAM            NO NETWORK TRANSITION LIMITS    YES REVOCABLE                    YES ```", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.PatientRightsRep, character: "患者權利代表", dialogue: "確認。與兩段回答一致。此記錄不追認十年研究。不允許其他用途。不允許永久使用。不允許將紗英數位化成靜態母體。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她簽名。時間戳。外部醫師簽名。時間戳。呼吸治療師簽署發聲閥程序記錄。時間戳。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:10。觀察室裡。獨立系統安全人員在另一個螢幕上輸入技術記錄。技術組正式區分兩種安全邊界。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "```text PATIENT SAFETY ENVELOPE   PER-PATIENT   OWN EEG   OWN BREATHING／AUTONOMIC   OWN SLEEP／WAKE RHYTHM   OWN NATURAL FAILURES   OWN MEDS／CLINICAL STATE   OWN LOCAL CONTROLLER HISTORY", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "NETWORK TRANSITION ENVELOPE   KAGAMI BUS TELEMETRY   + NATURAL／MAINTENANCE CUTOVER HISTORY   + M-00 ENDPOINT LIMITS   + PATIENT NODE SAFETY PROOFS ```", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "患者安全邊界——每名患者各自生成。只來自自己的資料。回答——對這一名患者而言，什麼狀態仍屬可接受的醫療安全範圍。網路過渡邊界——不是由 M-00 單獨定義。不是所有患者必須模仿紗英的共同標準。由匯流排遙測、自然切換、M-00 端點限制及患者節點安全證明共同生成。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他頓了一下。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "M-00 資料只回答——當目前的中央端點仍連在閉環上時，它能承受多快、多少幅度的網路改變。不回答——其他患者應該變成什麼樣。紗英不再是其他人的醫療答案。她只提供——目前中央端點在過渡期間不可跨越的其中一組限制。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她不是母體了。不是——她不再是答案。她只是——其中一組限制。過渡期間的限制。可撤回的。會過期的。不是永久的。不是定義所有人的。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:12。觀察室裡安靜了。螢幕上紗英的眼睛又閉上了。呼吸很慢。很穩。溝通板掛在床邊。STOP／NO USE。紅色。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原坐在角落。她看著螢幕。她的表情——變了。不是崩潰。不是動搖。是——第一次。她第一次看見。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她看見了。凪原看見了。她看見——紗英的同意不是「繼續維持」。不是「請繼續用我的資料維持系統」。是——「規定現有系統最多可以怎樣拆除」。紗英不是在授權系統繼續運作。她是在——寫規則。寫系統可以怎麼被拆掉的規則。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原的手指在膝蓋上鬆開了。不是放棄。是——她一直握著的東西。鬆了一點。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她一直相信——原始過濾是必要的。人類沒有準備好自由面對未來。未來必須先被整理。可是——紗英剛才做的事。不是被整理。是——她在整理系統。她在告訴系統——你可以怎麼離開我。你不可以拿走我的全部。你不可以把我送出去。你不可以把我變成永久的東西。你可以——慢慢拆。按我說的規則拆。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:13。澪看著螢幕。她的母親。閉著眼睛。呼吸很慢。溝通板上的紅字在螢幕裡很小。但——一直在那裡。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）這不是維持。這是——拆除的規則。母親不是在保護系統。她是在保護——拆除系統時不會有人受傷。包括她自己。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:15。外部醫師從病房走出來。他走進觀察室。他看著澪。他的表情很平。但他的眼睛——比進去時柔了一點。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "兩段一致。限制性同意有效。可撤回。SAFE PAUSE 已說明。溝通板 STOP／NO USE 永久在位。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯謝謝。", background: Background.Chapter_24_Ch24_Act2_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她沒有說更多。她看著螢幕。螢幕裡的紗英已經睡著了。或者——閉著眼睛。分不清。但呼吸器的節奏沒有變。很慢。很穩。", background: Background.Chapter_24_Ch24_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "距下一次星期一 06:13——約一日二十小時五十八分鐘。", background: Background.Chapter_24_Ch24_Act2_S0 },
];
